    public async Task<Dictionary<string, object>> ExecuteWorkflow()
    {
        _logger.LogInformation(
            "Starting workflow: {WorkflowName} SagaId={SagaId} CorrelationId={CorrelationId}",
            _workflow.Name,
            _sagaId,
            CorrelationId);
        InitializeVariables(_workflow.Variables);
        _compensationsRan = false;
        _compensationStack.Clear();

        if (_sagaStateStore != null)
        {
            await _sagaStateStore.StartAsync(new SagaStateRecord
            {
                SagaId = _sagaId,
                WorkflowName = _workflow.Name,
                Kind = _workflow.Kind,
                CorrelationId = CorrelationId
            });
        }

        // Transition-driven: start at the first step, then follow action targets.
        // Sibling steps under `steps:` are looked up by name (not nested step.Steps).
        if (_workflow.Steps.Count == 0)
        {
            _logger.LogWarning("Workflow {WorkflowName} has no steps", _workflow.Name);
            LastExecutionSucceeded = true;
            if (_sagaStateStore != null)
                await _sagaStateStore.CompleteAsync(_sagaId, SagaStatus.Completed);
            return BuildResultPayload();
        }

        var (firstStepName, firstStep) = _workflow.Steps.First();
        LastExecutionSucceeded = await ExecuteStep(firstStepName, firstStep);

        if (!LastExecutionSucceeded)
            await RunCompensationsAsync("workflow failed");

        if (_sagaStateStore != null)
        {
            var status = LastExecutionSucceeded
                ? SagaStatus.Completed
                : CompensatedSteps.Count > 0
                    ? SagaStatus.Compensated
                    : SagaStatus.Failed;
            await _sagaStateStore.CompleteAsync(
                _sagaId,
                status,
                LastExecutionSucceeded ? null : "workflow failed");
        }

        _logger.LogInformation(
            "Workflow {WorkflowName} completed. Success={Success} Compensated={CompensatedCount}",
            _workflow.Name,
            LastExecutionSucceeded,
            CompensatedSteps.Count);
        return BuildResultPayload();
    }

