    private object ResolveOutputToken(JToken token)
    {
        switch (token.Type)
        {
            case JTokenType.Object:
            {
                var obj = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
                foreach (var prop in ((JObject)token).Properties())
                    obj[prop.Name] = ResolveOutputToken(prop.Value);
                return obj;
            }
            case JTokenType.Array:
            {
                var list = new List<object>();
                foreach (var item in (JArray)token)
                    list.Add(ResolveOutputToken(item));
                return list;
            }
            case JTokenType.String:
            {
                var raw = token.Value<string>() ?? string.Empty;
                var replaced = ReplaceTokens(raw);
                if (replaced != raw && IsValidJson(replaced))
                {
                    try
                    {
                        return JsonSerializer.Deserialize<JsonElement>(replaced);
                    }
                    catch
                    {
                        // fall through to string / scalar parse
                    }
                }

                if (bool.TryParse(replaced, out var b)) return b;
                if (int.TryParse(replaced, System.Globalization.NumberStyles.Integer,
                        System.Globalization.CultureInfo.InvariantCulture, out var i))
                    return i;
                if (long.TryParse(replaced, System.Globalization.NumberStyles.Integer,
                        System.Globalization.CultureInfo.InvariantCulture, out var l))
                    return l;
                if (double.TryParse(replaced, System.Globalization.NumberStyles.Float,
                        System.Globalization.CultureInfo.InvariantCulture, out var d))
                    return d;

                return replaced;
            }
            case JTokenType.Integer:
                return token.Value<long>();
            case JTokenType.Float:
                return token.Value<double>();
            case JTokenType.Boolean:
                return token.Value<bool>();
            case JTokenType.Null:
            case JTokenType.Undefined:
                return null!;
            default:
                return token.ToString();
        }
    }

    private TimeSpan CalculateBackoffDelay(int retryAttempt)
    {
        var baseDelay = GetVariable<int>("retryBaseDelayMs", 1000);
        var maxDelay = GetVariable<int>("maxRetryDelayMs", 30000);

        var exponentialDelay = baseDelay * Math.Pow(2, retryAttempt);
        var withJitter = exponentialDelay * (0.5 + Random.Shared.NextDouble());

        return TimeSpan.FromMilliseconds(Math.Min(withJitter, maxDelay));
    }

