    private async Task<bool> ExecuteStep(string stepName, Step step)
    {
        _logger.LogInformation("Executing step: {StepName}", stepName);

        if (!string.IsNullOrEmpty(step.Condition) && !EvaluateCondition(step.Condition, null))
        {
            _logger.LogInformation("Skipping step {StepName} due to condition", stepName);
            return true;
        }

        if (step.DependsOn != null && step.DependsOn.Any(dep => !_results.ContainsKey($"{dep}.response")))
        {
            _logger.LogWarning("Dependencies not met for step {StepName}", stepName);
            return false;
        }

        if (!string.IsNullOrEmpty(step.Repeat))
        {
            var maxRetries = EvaluateExpression(step.Repeat);
            var currentRetry = 0;
            var success = false;

            while (!success && currentRetry < maxRetries)
            {
                _variables["currentRetryCount"] = currentRetry;
                success = await ExecuteStepWithRetry(stepName, CloneStepWithoutRepeat(step), currentRetry);

                if (!success)
                {
                    var delay = CalculateBackoffDelay(currentRetry);
                    await Task.Delay(delay);
                    currentRetry++;
                }
            }

            return success;
        }

        if (step.IsParallelCoordinator)
        {
            return await ExecuteParallelAsync(stepName, step);
        }

        if (step.IsForeachCoordinator)
        {
            return await ExecuteForeachAsync(stepName, step);
        }

        // Virtual / transition-only step (no URL) — e.g. successPartial routing hubs.
        if (string.IsNullOrWhiteSpace(step.Url))
        {
            return await ExecuteVirtualStep(stepName, step);
        }

        return await ExecuteHttpStep(stepName, step, followTransitions: true, CancellationToken.None);
    }

    private async Task<bool> ExecuteVirtualStep(string stepName, Step step)
