            _results[$"{stepName}.response"] = JsonSerializer.SerializeToElement(new { ok = true });
        }

        var branched = await TryFollowStepTransitions(
            stepName, step, JsonSerializer.SerializeToElement(new { ok = true }));
        return branched ?? true;
    }

    private async Task<bool> ExecuteParallelAsync(string stepName, Step step)
    {
        var joined = await RunNamedHttpStepsAsync(step.Parallel, step.Join, CancellationToken.None);
        StoreCoordinatorResult(stepName, joined);
        return await FollowCoordinatorTransitions(stepName, step, CoordinatorResult(joined), joined);
