    private async Task<bool> ExecuteForeachAsync(string stepName, Step step)
    {
        var items = ResolveForeachArray(step.Foreach);
        var maxItems = step.MaxItems is > 0
            ? Math.Min(step.MaxItems.Value, WorkflowValidator.MaxForeachItems)
            : WorkflowValidator.MaxForeachItems;
        var alias = string.IsNullOrWhiteSpace(step.As) ? "item" : step.As;
        var itemStepName = step.ForeachItemStep!;
        if (!_workflow.Steps.TryGetValue(itemStepName, out var itemStep))
        {
            _logger.LogWarning("Foreach {StepName} item step {ItemStep} is missing", stepName, itemStepName);
            StoreCoordinatorResult(stepName, false);
            return false;
        }

        var slice = items.Take(maxItems).ToList();
        if (slice.Count == 0)
        {
            _logger.LogInformation("Foreach {StepName} has no items; continuing", stepName);
            StoreCoordinatorResult(stepName, true);
            return await FollowCoordinatorTransitions(stepName, step, CoordinatorResult(true), true);
        }

        var ok = IsParallelForeach(step.Mode)
            ? await RunForeachParallelAsync(alias, itemStepName, itemStep, slice)
            : await RunForeachSequentialAsync(alias, itemStepName, itemStep, slice);

        StoreCoordinatorResult(stepName, ok);
        return await FollowCoordinatorTransitions(stepName, step, CoordinatorResult(ok), ok);
    }

    private async Task<bool> RunForeachSequentialAsync(
        string alias, string itemStepName, Step itemStep, List<JToken> items)
    {
        var index = 0;
        var ok = true;
        foreach (var item in items)
        {
            var itemOk = await ExecuteHttpStep(
                itemStepName, itemStep, followTransitions: false, CancellationToken.None, alias, item,
                $"{itemStepName}.{index}");
            if (!itemOk)
            {
                ok = false;
                break;
            }

            index++;
        }

        return ok;
    }

    private async Task<bool> RunForeachParallelAsync(
        string alias, string itemStepName, Step itemStep, List<JToken> items)
    {
        var ok = true;
        for (var offset = 0; offset < items.Count; offset += WorkflowValidator.MaxParallelBranches)
        {
            var chunk = items.Skip(offset).Take(WorkflowValidator.MaxParallelBranches).ToList();
            var chunkTasks = chunk.Select((item, i) =>
            {
                var index = offset + i;
                return RunForeachItemAsync(alias, itemStepName, itemStep, item, index);
            });
            var chunkResults = await Task.WhenAll(chunkTasks);
            if (chunkResults.Any(r => !r))
            {
                ok = false;
                break;
            }
        }

        return ok;
    }

    private async Task<bool> RunForeachItemAsync(
        string alias, string itemStepName, Step itemStep, JToken item, int index)
    {
        var itemOk = await ExecuteHttpStep(
            itemStepName, itemStep, followTransitions: false, CancellationToken.None, alias, item,
            $"{itemStepName}.{index}");
        return itemOk;
    }

    private async Task<bool> RunNamedHttpStepsAsync(
        IReadOnlyList<string> names, string? join, CancellationToken cancellationToken)
    {
        var joinMode = NormalizeJoin(join);
        if (names.Count == 0)
        {
            return true;
        }

        if (joinMode == "failfast")
        {
            using var failFast = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
            var tasks = names.Select(name => RunNamedHttpChildAsync(name, failFast)).ToList();
            var results = await Task.WhenAll(tasks);
            return results.All(x => x);
        }

        var allResults = await Task.WhenAll(names.Select(name => RunNamedHttpChildAsync(name, null)));
        return joinMode == "any" ? allResults.Any(x => x) : allResults.All(x => x);
    }

    private async Task<bool> RunNamedHttpChildAsync(string name, CancellationTokenSource? failFastCts)
    {
        if (!_workflow.Steps.TryGetValue(name, out var child))
        {
            _logger.LogWarning("Parallel child {StepName} is missing", name);
            failFastCts?.Cancel();
            return false;
        }

        try
        {
            var token = failFastCts?.Token ?? CancellationToken.None;
            var ok = await ExecuteHttpStep(name, child, followTransitions: false, token, null, null);
            if (!ok)
            {
                failFastCts?.Cancel();
            }

            return ok;
        }
        catch (OperationCanceledException)
        {
            return false;
        }
    }

    private void StoreCoordinatorResult(string stepName, bool ok)
    {
        var status = ok ? 200 : 500;
        lock (_results)
        {
            _results[$"{stepName}.statusCode"] = status;
            _results[$"{stepName}.response"] = JsonSerializer.SerializeToElement(new { ok });
        }
    }

    private static JsonElement CoordinatorResult(bool ok) =>
        JsonSerializer.SerializeToElement(new { ok });

    private static string NormalizeJoin(string? join) =>
        string.IsNullOrWhiteSpace(join) ? "all" : join.Trim().ToLowerInvariant();

    private static bool IsParallelForeach(string? mode) =>
        !string.IsNullOrWhiteSpace(mode) && mode.Equals("parallel", StringComparison.OrdinalIgnoreCase);

    private JArray ResolveForeachArray(string foreachExpr)
    {
        var trimmed = foreachExpr.Trim();
        var tokenMatch = Regex.Match(trimmed, @"^\{\{\s*(.+?)\s*\}\}$");
        if (tokenMatch.Success)
        {
            var key = tokenMatch.Groups[1].Value.Trim();
            if (TryExtractKey("input.", key, out var inputKey))
            {
                return ToJArray(_kafkaMessage.SelectToken(inputKey));
            }
        }

        var replaced = ReplaceTokens(trimmed);
        if (string.IsNullOrWhiteSpace(replaced) || replaced == trimmed)
        {
            return [];
        }

        try
        {
            var parsed = JToken.Parse(replaced);
            return ToJArray(parsed);
        }
        catch (Exception)
        {
            return [];
        }
    }

    private static JArray ToJArray(JToken? token) =>
        token switch
        {
            null => [],
            JArray array => array,
            _ => [token]
        };

    private async Task<bool> ExecuteHttpStep(
        string stepName,
        Step step,
        bool followTransitions,
        CancellationToken cancellationToken,
        string? itemAlias = null,
        JToken? itemValue = null,
        string? resultKey = null)
    {
        HttpRequestMessage request;
        lock (_itemScopes)
        {
            if (itemAlias != null && itemValue != null)
            {
                _itemScopes[itemAlias] = itemValue;
            }

            request = BuildHttpRequest(step);

            if (itemAlias != null)
            {
                _itemScopes.Remove(itemAlias);
            }
        }

        try
        {
            using var timeoutCts = new CancellationTokenSource(TimeSpan.FromSeconds(step.TimeoutSeconds ?? 30));
            using var linkedCts = CancellationTokenSource.CreateLinkedTokenSource(timeoutCts.Token, cancellationToken);
            var response = await _httpClient.SendAsync(request, linkedCts.Token);

            var storeKey = resultKey ?? stepName;
            lock (_results)
            {
                _results[$"{storeKey}.statusCode"] = (int)response.StatusCode;
            }

            var content = await response.Content.ReadAsStringAsync(linkedCts.Token);

            var result = IsValidJson(content) ? JsonSerializer.Deserialize<JsonElement>(content) : (JsonElement?)null;
            lock (_results)
            {
                _results[$"{storeKey}.response"] = result!;
            }

            if (response.IsSuccessStatusCode && !_compensationsRan)
                await RegisterCompensationAsync(stepName, step);

            if (followTransitions)
            {
                var branched = await TryFollowStepTransitions(stepName, step, result);
                if (branched.HasValue)
                {
                    return branched.Value;
                }
            }

            _logger.LogInformation("Step {StepName} completed with status code {StatusCode}",
                stepName, response.StatusCode);
            return response.IsSuccessStatusCode;
        }
        catch (OperationCanceledException)
        {
            _logger.LogWarning("Step {StepName} timed out", stepName);
            return false;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error executing step {StepName}", stepName);
            return false;
        }
    }

    private async Task RegisterCompensationAsync(string stepName, Step step)
    {
        if (string.IsNullOrWhiteSpace(step.Compensate))
            return;

        _compensationStack.Push((stepName, step.Compensate.Trim()));
        if (_sagaStateStore != null)
            await _sagaStateStore.MarkStepCompletedAsync(_sagaId, stepName);

        _logger.LogInformation(
            "Registered compensate {Compensate} for step {StepName}",
            step.Compensate,
            stepName);
    }

    /// <summary>
    /// Runs compensate steps LIFO when the workflow fails.
    /// Prefer YAML <c>compensate:</c> on mutating steps + terminal <c>fail</c>; do not also transition to the same compensate step.
    /// </summary>
    private async Task RunCompensationsAsync(string reason)
    {
        if (_compensationsRan || _compensationStack.Count == 0)
            return;

        _compensationsRan = true;
        _logger.LogWarning(
            "Running {Count} compensation(s) for saga {SagaId}. Reason={Reason}",
            _compensationStack.Count,
            _sagaId,
            reason);

        if (_sagaStateStore != null)
            await _sagaStateStore.MarkCompensatingAsync(_sagaId);

        var ran = new List<string>();
        while (_compensationStack.Count > 0)
        {
            var (stepName, compensateName) = _compensationStack.Pop();
            if (!_workflow.Steps.TryGetValue(compensateName, out var compensateStep))
            {
                _logger.LogError(
                    "Compensate step {Compensate} for {StepName} not found",
                    compensateName,
                    stepName);
                continue;
            }

            _logger.LogInformation(
                "Compensating {StepName} via {Compensate}",
                stepName,
                compensateName);

            // Compensate steps run without following their transitions (avoid loops).
            var ok = string.IsNullOrWhiteSpace(compensateStep.Url)
                ? true
                : await ExecuteHttpStep(
                    compensateName,
                    compensateStep,
                    followTransitions: false,
                    CancellationToken.None);

            if (!ok)
            {
                _logger.LogError(
                    "Compensate step {Compensate} failed for {StepName}",
                    compensateName,
                    stepName);
            }

            ran.Add(compensateName);
            if (_sagaStateStore != null)
                await _sagaStateStore.MarkStepCompensatedAsync(_sagaId, compensateName);
        }

        CompensatedSteps = ran;
    }

    private HttpRequestMessage BuildHttpRequest(Step step)
    {
        var url = InitializeBaseUrl(step.Url);
        var request = new HttpRequestMessage(new HttpMethod(step.Method), url);
        string? contentType = null;
        if (step.Headers != null)
        {
            foreach (var (key, value) in step.Headers)
            {
                var replaced = ReplaceTokens(value);
                if (key.Equals("Content-Type", StringComparison.OrdinalIgnoreCase))
                {
                    contentType = replaced;
                    continue;
                }

                request.Headers.TryAddWithoutValidation(key, replaced);
            }
        }

        if (!string.IsNullOrWhiteSpace(CorrelationId)
            && !request.Headers.Contains("X-Correlation-Id"))
        {
            request.Headers.TryAddWithoutValidation("X-Correlation-Id", CorrelationId);
        }

        if (step.Body is { Count: > 0 })
        {
            var jsonBody = ReplaceTokens(step.Body.ToString());
            request.Content = new StringContent(
                jsonBody,
                System.Text.Encoding.UTF8,
                contentType ?? "application/json");
        }

        return request;
    }

    private async Task<bool?> TryFollowStepTransitions(string stepName, Step step, JsonElement? result)
    {
        if (step.Transitions is not { Count: > 0 })
        {
            return null;
        }

        foreach (var action in step.Transitions)
        {
            if (!EvaluateCondition(action.Condition, result))
            {
                continue;
            }

            if (IsTerminalAction(action.Action))
            {
                _logger.LogInformation("Step {StepName} reached terminal action {Action}", stepName, action.Action);
                // Align with FollowCoordinatorTransitions: fail => false, success/end => true.
                return !action.Action.Equals("fail", StringComparison.OrdinalIgnoreCase);
            }

            if (!_workflow.Steps.TryGetValue(action.Action, out var nextStep))
            {
                _logger.LogWarning(
                    "Transition from {StepName} targets unknown step {Action}",
                    stepName,
                    action.Action);
                return false;
            }

            return await ExecuteStep(action.Action, nextStep);
        }

        return null;
    }

    private async Task<bool> FollowCoordinatorTransitions(
        string stepName, Step step, JsonElement? result, bool joinSucceeded)
    {
        if (step.Transitions is not { Count: > 0 })
        {
            return joinSucceeded;
        }

        foreach (var action in step.Transitions)
        {
            if (!EvaluateCondition(action.Condition, result))
            {
                continue;
            }

            if (IsTerminalAction(action.Action))
            {
                _logger.LogInformation("Step {StepName} reached terminal action {Action}", stepName, action.Action);
                return !action.Action.Equals("fail", StringComparison.OrdinalIgnoreCase);
            }

            if (!_workflow.Steps.TryGetValue(action.Action, out var nextStep))
            {
                _logger.LogWarning(
                    "Transition from {StepName} targets unknown step {Action}",
                    stepName,
                    action.Action);
                return false;
            }

            return await ExecuteStep(action.Action, nextStep);
        }

        return joinSucceeded;
    }

    private void InitializeVariables(Dictionary<string, VariableDefinition> variables)
    {
        foreach (var (key, value) in variables)
        {
            _variables[key] = ParseValue(value.Type, ReplaceTokens(value.Value.ToString()!));
        }
    }

    private string InitializeBaseUrl(string url)
    {
        return ReplaceTokens(url ?? string.Empty);
    }

    private bool EvaluateCondition(string condition, JsonElement? stepResult)
    {
        if (string.IsNullOrWhiteSpace(condition) || condition == "default")
        {
            return true;
        }

        var andConditions = condition.Split("&&", StringSplitOptions.RemoveEmptyEntries);
        return andConditions.All(andCondition =>
        {
            var orConditions = andCondition.Split("||", StringSplitOptions.RemoveEmptyEntries);
            return orConditions.Any(orCondition => EvaluateSingleCondition(orCondition.Trim(), stepResult));
        });
    }

    private bool EvaluateSingleCondition(string condition, JsonElement? stepResult)
    {
        var match = Regex.Match(condition, @"(\w+(?:\.\w+)*)\s*(==|!=|>|<|>=|<=)\s*(.+)");
        if (!match.Success) return false;

        var leftPart = match.Groups[1].Value.Trim();
        var operatorPart = match.Groups[2].Value.Trim();
        var rightPart = match.Groups[3].Value.Trim();

        var leftValue = GetValue(leftPart, stepResult);
        var rightValue = GetValue(rightPart, stepResult);

        return CompareValues(leftValue, operatorPart, rightValue);
    }

    private object GetValue(string path, JsonElement? stepResult)
    {
        if (path.StartsWith("response.") && stepResult.HasValue)
        {
            var property = path.Substring("response.".Length);
            if (stepResult.Value.TryGetProperty(property, out JsonElement value))
            {
                return value;
            }
        }
        else if (_variables.TryGetValue(path, out var value))
        {
            return value;
        }
        else if (_results.TryGetValue(path, out var resultValue))
        {
            return resultValue;
        }
        return path.Trim('\"');
    }

    private bool CompareValues(object left, string op, object right)
    {
        if (left is JsonElement leftElement && right is JsonElement rightElement)
        {
            return CompareJsonElements(leftElement, op, rightElement);
        }

        if (double.TryParse(left?.ToString(), out double leftDouble) && double.TryParse(right?.ToString(), out double rightDouble))
        {
            return op switch
            {
                "==" => Math.Abs(leftDouble - rightDouble) < 0.000001,
                "!=" => Math.Abs(leftDouble - rightDouble) >= 0.000001,
                ">" => leftDouble > rightDouble,
                "<" => leftDouble < rightDouble,
                ">=" => leftDouble >= rightDouble,
                "<=" => leftDouble <= rightDouble,
                _ => false
            };
        }
        else
        {
            return op switch
            {
                "==" => left?.ToString() == right?.ToString(),
                "!=" => left?.ToString() != right?.ToString(),
                _ => false
            };
        }
    }

    private bool CompareJsonElements(JsonElement left, string op, JsonElement right)
    {
        switch (left.ValueKind)
        {
            case JsonValueKind.Number:
                return CompareValues(left.GetDouble(), op, right.GetDouble());
            case JsonValueKind.String:
                return CompareValues(left.GetString()!, op, right.GetString()!);
            case JsonValueKind.True:
            case JsonValueKind.False:
                return CompareValues(left.GetBoolean(), op, right.GetBoolean());
            default:
                return false;
        }
    }

    private string ReplaceTokens(string input)
    {
        return Regex.Replace(input, @"\{\{(.*?)\}\}", match =>
        {
            var key = match.Groups[1].Value.Trim();

            if (TryExtractKey("QuickcodeClients.", key, out _)
                || TryExtractKey("ThirdPartyServices.", key, out _))
            {
                var configApiKey = _configuration.GetValue<string>(key.Replace('.', ':'));
                return string.IsNullOrWhiteSpace(configApiKey) ? match.Value : configApiKey.TrimEnd('/');
            }

            if (TryExtractKey("parameters.", key, out var parameterPath))
            {
                var value = ResolveConfigPath(
                    parameterPath,
                    "WorkflowParameters",
                    "Parameters");
                return value != null ? value.TrimEnd('/') : match.Value;
            }

            if (TryExtractKey("secrets.", key, out var secretPath))
            {
                return ResolveConfigPath(secretPath, "WorkflowSecrets", "Secrets")
                       ?? match.Value;
            }

            if (TryExtractKey("GatewayServiceToken.", key, out var targetModule))
            {
                return _tokenGenerator.Create(targetModule);
            }

            if (TryExtractKey("variables.", key, out var variableKey))
            {
                return GetValueFromDictionary(_variables, variableKey, match.Value);
            }

            if (TryExtractKey("input.", key, out var inputKey))
            {
                return GetValueFromQueryCollection(_kafkaMessage, inputKey, match.Value);
            }

            var itemValue = ResolveItemScopeToken(key, match.Value);
            if (itemValue != match.Value)
            {
                return itemValue;
            }

            return ResolveResultToken(key, match.Value);
        });
    }

    private string ResolveItemScopeToken(string key, string fallback)
    {
        foreach (var (alias, token) in _itemScopes)
        {
            if (key.Equals(alias, StringComparison.OrdinalIgnoreCase))
            {
                return token.ToString();
            }

            var prefix = alias + ".";
            if (!key.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            var path = key[prefix.Length..];
            if (token is JObject obj)
            {
                return obj.GetPathValue(path) ?? fallback;
            }

            return token.SelectToken(path)?.ToString() ?? fallback;
        }

        return fallback;
    }

    private string ResolveResultToken(string key, string fallback)
    {
        if (_results.TryGetValue(key, out var exact))
        {
            return exact?.ToString() ?? fallback;
        }

        // Support {{resolveUser.response.permissionGroupName}} against JsonElement results.
        var dotIndex = key.IndexOf('.');
        while (dotIndex > 0)
        {
            var prefix = key[..dotIndex];
            var remainder = key[(dotIndex + 1)..];
            if (_results.TryGetValue(prefix, out var value))
            {
                if (value is JsonElement element)
                {
                    var token = element;
                    foreach (var segment in remainder.Split('.', StringSplitOptions.RemoveEmptyEntries))
                    {
                        if (token.ValueKind != JsonValueKind.Object || !token.TryGetProperty(segment, out token))
                        {
                            return fallback;
                        }
                    }

                    return token.ToString() ?? fallback;
                }

                return value?.ToString() ?? fallback;
            }

            dotIndex = key.IndexOf('.', dotIndex + 1);
        }

        return fallback;
    }

    private bool TryExtractKey(string prefix, string fullKey, out string extractedKey)
    {
        if (fullKey.StartsWith(prefix))
        {
            extractedKey = fullKey[prefix.Length..];
            return true;
        }

        extractedKey = string.Empty;
        return false;
    }

    /// <summary>
    /// Resolves nested config keys: <c>parameters.IyzicoPos.BaseUrl</c> →
    /// <c>WorkflowParameters:IyzicoPos:BaseUrl</c> (then fallback section).
    /// </summary>
    private string? ResolveConfigPath(string dottedPath, params string[] sectionRoots)
    {
        var colonPath = dottedPath.Replace('.', ':');
        foreach (var root in sectionRoots)
        {
            var value = _configuration[$"{root}:{colonPath}"];
            if (!string.IsNullOrWhiteSpace(value))
                return value;
        }

        return null;
    }

    private string GetValueFromDictionary(Dictionary<string, object> dictionary, string key, string fallback)
    {
        return dictionary.TryGetValue(key, out var value) ? value?.ToString() ?? fallback : fallback;
    }

    private string GetValueFromQueryCollection(JObject value, string key, string fallback)
    {
        return value.GetPathValue(key) ?? fallback;
    }

    private int EvaluateExpression(string expression)
    {
        return int.Parse(ReplaceTokens(expression));
    }

    private object ParseValue(string type, string value)
    {
        return type switch
        {
            "int" => int.Parse(value),
            "bool" => bool.Parse(value),
            "double" => double.Parse(value),
            _ => value
        };
    }
}
